MOTIF_NAME = 'material advantage or hanging enemy piece'
MOTIF_DESCRIPTION = 'The side to move is at least a pawn ahead in material, or material is level while an enemy minor piece or better hangs to a free or favorable capture.'

import chess

def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except Exception:
        return False
    stm = board.turn
    opp = not stm
    vals = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}
    diff = 0
    for pt, v in vals.items():
        diff += v * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
    if diff >= 1:
        return True
    if diff < 0 or board.is_check():
        return False
    best = 0
    for pt in (chess.QUEEN, chess.ROOK, chess.BISHOP, chess.KNIGHT):
        v = vals[pt]
        for sq in board.pieces(pt, opp):
            atts = [a for a in board.attackers(stm, sq) if not board.is_pinned(stm, a)]
            if not atts:
                continue
            defs = board.attackers(opp, sq)
            if not defs:
                gain = v
            else:
                ca = min(vals.get(board.piece_at(a).piece_type, 99) for a in atts)
                gain = v - ca if ca < v else 0
            if gain > best:
                best = gain
    return best >= 3

MOTIF_NAME = 'consolidated queenless material lead or dual margin-trump parity edge'
MOTIF_DESCRIPTION = 'Not in check, with no unit hanging or attacked by a cheaper piece, a calm own king ring and no advanced enemy passer, the side to move is either a clean point or more up in a fully queenless position (a single-pawn edge requiring one comparative trump) or at exact material parity holding two or more margin trumps among passers, pawn health, rook activity, bishop pair, outposts, space, development and king quality.'

import chess

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    if board.is_check():
        return False
    V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}
    diff = 0
    for pt in V:
        diff += V[pt] * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
    if diff < 0:
        return False
    for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        for s in board.pieces(pt, stm):
            atk = board.attackers(opp, s)
            if not atk:
                continue
            if not board.attackers(stm, s):
                return False
            mn = 99
            for a in atk:
                q = board.piece_at(a)
                v = V.get(q.piece_type, 99)
                if v < mn:
                    mn = v
            if mn < V[pt]:
                return False
    for s in board.pieces(chess.PAWN, stm):
        if len(board.attackers(opp, s)) > len(board.attackers(stm, s)):
            return False
    mk = board.king(stm)
    ok = board.king(opp)
    ring = set()
    for s in chess.SQUARES:
        if chess.square_distance(s, mk) <= 1:
            for a in board.attackers(opp, s):
                if a != ok:
                    ring.add(a)
    if len(ring) >= 3:
        return False

    def rel(sq, c):
        r = chess.square_rank(sq)
        return r if c == chess.WHITE else 7 - r

    def passers(c):
        res = []
        for p in board.pieces(chess.PAWN, c):
            f = chess.square_file(p)
            rr = rel(p, c)
            blocked = False
            for q in board.pieces(chess.PAWN, not c):
                if abs(chess.square_file(q) - f) <= 1 and rel(q, c) > rr:
                    blocked = True
                    break
            if not blocked:
                res.append(rr)
        return res

    mp = passers(stm)
    tp = passers(opp)
    if tp and max(tp) >= 5:
        return False
    t = 0
    if len(mp) > len(tp):
        t += 1
    if mp and max(mp) >= 5:
        t += 1

    def weak(c):
        cnt = [0] * 8
        for p in board.pieces(chess.PAWN, c):
            cnt[chess.square_file(p)] += 1
        w = 0
        for f in range(8):
            if cnt[f] >= 2:
                w += cnt[f] - 1
            if cnt[f] and (f == 0 or cnt[f - 1] == 0) and (f == 7 or cnt[f + 1] == 0):
                w += cnt[f]
        return w
    if weak(opp) >= weak(stm) + 2:
        t += 1

    def rookact(c):
        n = 0
        for r in board.pieces(chess.ROOK, c):
            f = chess.square_file(r)
            own = False
            for p in board.pieces(chess.PAWN, c):
                if chess.square_file(p) == f and rel(p, c) > rel(r, c):
                    own = True
                    break
            if not own or rel(r, c) >= 6:
                n += 1
        return n
    if rookact(stm) > rookact(opp):
        t += 1

    if len(board.pieces(chess.BISHOP, stm)) >= 2 and len(board.pieces(chess.BISHOP, opp)) <= 1:
        t += 1

    def outp(c):
        n = 0
        for pt in (chess.KNIGHT, chess.BISHOP):
            for s in board.pieces(pt, c):
                rr = rel(s, c)
                if rr < 4 or rr > 6:
                    continue
                pd = False
                for a in board.attackers(c, s):
                    q = board.piece_at(a)
                    if q is not None and q.piece_type == chess.PAWN:
                        pd = True
                        break
                if not pd:
                    continue
                f = chess.square_file(s)
                safe = True
                for q in board.pieces(chess.PAWN, not c):
                    if abs(chess.square_file(q) - f) == 1 and rel(q, c) > rr:
                        safe = False
                        break
                if safe:
                    n += 1
        return n
    if outp(stm) >= 1 and outp(opp) == 0:
        t += 1

    sp = 0
    for p in board.pieces(chess.PAWN, stm):
        if rel(p, stm) >= 4:
            sp += 1
    so = 0
    for p in board.pieces(chess.PAWN, opp):
        if rel(p, opp) >= 4:
            so += 1
    if sp >= so + 2:
        t += 1

    dm = 0
    do = 0
    for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        for s in board.pieces(pt, stm):
            if rel(s, stm) >= 1:
                dm += 1
        for s in board.pieces(pt, opp):
            if rel(s, opp) >= 1:
                do += 1
    if dm >= do + 2:
        t += 1

    qless = (not board.pieces(chess.QUEEN, stm)) and (not board.pieces(chess.QUEEN, opp))
    if qless:
        if rel(mk, stm) >= 3 and rel(mk, stm) > rel(ok, opp):
            t += 1
    else:
        def shel(c):
            k = board.king(c)
            kf = chess.square_file(k)
            n = 0
            for p in board.pieces(chess.PAWN, c):
                if abs(chess.square_file(p) - kf) <= 1 and 1 <= rel(p, c) - rel(k, c) <= 2:
                    n += 1
            return n
        if rel(mk, stm) <= 1 and shel(stm) >= shel(opp) + 2:
            t += 1

    if qless and diff >= 1:
        return diff >= 2 or t >= 1
    if diff == 0 and t >= 2:
        return True
    return False

import chess

MOTIF_NAME = 'concrete target with safe camp at material parity or better'
MOTIF_DESCRIPTION = 'Not behind in material, not in check, and with none of its own pieces profitably capturable, the side to move owns a concrete target: a static-exchange-winning capture, a besieged weak enemy pawn, exclusive heavy-piece infiltration, a safe advanced passer, a trapped ventured enemy minor, or a dominant attack on the enemy king ring.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 99}
    PTS = (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN)

    def mval(c):
        return sum(V[pt] * len(board.pieces(pt, c)) for pt in PTS)

    if mval(stm) < mval(opp) or board.is_check():
        return False

    def alist(color, sq, excl=-1):
        return sorted(V[board.piece_at(s).piece_type] for s in board.attackers(color, sq) if s != excl)

    def swap(v0, a0, first, second):
        gains = [v0]
        occ = a0
        cur, oth = first, second
        while cur:
            nxt = cur.pop(0)
            gains.append(occ - gains[-1])
            occ = nxt
            cur, oth = oth, cur
        for i in range(len(gains) - 1, 0, -1):
            gains[i - 1] = -max(-gains[i - 1], gains[i])
        return gains[0]

    threat = 0
    for pt in PTS:
        for s in board.pieces(pt, stm):
            atts = alist(opp, s)
            if not atts:
                continue
            a0 = atts.pop(0)
            g = swap(V[pt], a0, alist(stm, s), atts)
            if g > threat:
                threat = g
    if threat > 1:
        return False

    for m in board.legal_moves:
        if not board.is_capture(m):
            continue
        to = m.to_square
        v0 = 1 if board.is_en_passant(m) else V[board.piece_at(to).piece_type]
        a0 = V[board.piece_at(m.from_square).piece_type]
        if swap(v0, a0, alist(opp, to), alist(stm, to, m.from_square)) >= 1:
            return True

    def rel(sq, c):
        r = chess.square_rank(sq)
        return r if c == chess.WHITE else 7 - r

    for s in board.pieces(chess.PAWN, opp):
        f = chess.square_file(s)
        r = chess.square_rank(s)
        supported = False
        for s2 in board.pieces(chess.PAWN, opp):
            if abs(chess.square_file(s2) - f) == 1:
                r2 = chess.square_rank(s2)
                if (opp == chess.WHITE and r2 < r) or (opp == chess.BLACK and r2 > r):
                    supported = True
                    break
        if supported:
            continue
        atk = len(board.attackers(stm, s))
        if atk >= 2 and atk >= len(board.attackers(opp, s)):
            return True

    inf_own = any(rel(s, stm) >= 6 for pt in (chess.ROOK, chess.QUEEN) for s in board.pieces(pt, stm))
    inf_opp = any(rel(s, opp) >= 6 for pt in (chess.ROOK, chess.QUEEN) for s in board.pieces(pt, opp))
    if inf_own and not inf_opp:
        return True

    for s in board.pieces(chess.PAWN, stm):
        if rel(s, stm) < 4:
            continue
        f = chess.square_file(s)
        r = chess.square_rank(s)
        passed = True
        for s2 in board.pieces(chess.PAWN, opp):
            if abs(chess.square_file(s2) - f) <= 1:
                r2 = chess.square_rank(s2)
                if (stm == chess.WHITE and r2 > r) or (stm == chess.BLACK and r2 < r):
                    passed = False
                    break
        if not passed:
            continue
        fr = r + 1 if stm == chess.WHITE else r - 1
        fsq = chess.square(f, fr)
        if board.piece_at(fsq) is None and len(board.attackers(stm, fsq)) >= len(board.attackers(opp, fsq)):
            return True

    pawn_att = set()
    for p in board.pieces(chess.PAWN, stm):
        for t in board.attacks(p):
            pawn_att.add(t)
    for pt in (chess.KNIGHT, chess.BISHOP):
        for s in board.pieces(pt, opp):
            if rel(s, opp) < 3:
                continue
            mob = 0
            for t in board.attacks(s):
                pc = board.piece_at(t)
                if (pc is not None and pc.color == opp) or t in pawn_att:
                    continue
                mob += 1
            if mob <= 1:
                return True

    ok = board.king(opp)
    ow = board.king(stm)
    if ok is not None and ow is not None:
        a1 = sum(len(board.attackers(stm, t)) for t in board.attacks(ok))
        a2 = sum(len(board.attackers(opp, t)) for t in board.attacks(ow))
        if a1 >= 3 and a1 - a2 >= 3:
            return True

    return False

import chess

MOTIF_NAME = 'positional edge at level material'
MOTIF_DESCRIPTION = 'With no material advantage, the side to move holds a clear positional plus from safe piece mobility, pressure on the enemy king zone, passed pawns, open rook files, king shelter and the bishop pair, while none of its own pieces are loose.'

def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except Exception:
        return False
    stm = board.turn
    opp = not stm
    V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}
    mat = 0
    for pt in V:
        mat += V[pt] * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
    if mat > 0 or mat < -2:
        return False
    pawn_atk = {}
    for c in (stm, opp):
        bb = 0
        for sq in board.pieces(chess.PAWN, c):
            bb |= int(board.attacks(sq))
        pawn_atk[c] = bb
    score = 0
    pieces4 = (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN)
    for c, sgn in ((stm, 1), (opp, -1)):
        own = board.occupied_co[c]
        epa = pawn_atk[not c]
        mob = 0
        for pt in pieces4:
            for sq in board.pieces(pt, c):
                for a in board.attacks(sq):
                    if (own >> a) & 1:
                        continue
                    if (epa >> a) & 1:
                        continue
                    mob += 1
        score += sgn * mob
        ek = board.king(not c)
        if ek is not None:
            ring = int(board.attacks(ek)) | (1 << ek)
            hits = 0
            for pt in pieces4:
                for sq in board.pieces(pt, c):
                    hits += len(board.attacks(sq) & ring)
            score += sgn * 2 * hits
        for sq in board.pieces(chess.PAWN, c):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            passed = True
            for ep in board.pieces(chess.PAWN, not c):
                if abs(chess.square_file(ep) - f) <= 1:
                    er = chess.square_rank(ep)
                    if (c and er > r) or ((not c) and er < r):
                        passed = False
                        break
            if passed:
                rel = r if c else 7 - r
                score += sgn * (rel - 1)
        own_pf = set(chess.square_file(x) for x in board.pieces(chess.PAWN, c))
        opp_pf = set(chess.square_file(x) for x in board.pieces(chess.PAWN, not c))
        for sq in board.pieces(chess.ROOK, c):
            f = chess.square_file(sq)
            if f not in own_pf:
                score += sgn * (2 if f not in opp_pf else 1)
        k = board.king(c)
        if k is not None:
            kf = chess.square_file(k)
            kr = chess.square_rank(k)
            sh = 0
            for sq in board.pieces(chess.PAWN, c):
                if abs(chess.square_file(sq) - kf) <= 1:
                    dr = chess.square_rank(sq) - kr
                    if not c:
                        dr = -dr
                    if 1 <= dr <= 2:
                        sh += 1
            score += sgn * min(sh, 3)
    if len(board.pieces(chess.BISHOP, stm)) >= 2 and len(board.pieces(chess.BISHOP, opp)) < 2:
        score += 2
    if len(board.pieces(chess.BISHOP, opp)) >= 2 and len(board.pieces(chess.BISHOP, stm)) < 2:
        score -= 2
    AV = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 99}
    for pt in pieces4:
        for sq in board.pieces(pt, stm):
            atk = board.attackers(opp, sq)
            if atk:
                if not board.attackers(stm, sq):
                    score -= 3
                else:
                    m = 99
                    for a in atk:
                        av = AV[board.piece_at(a).piece_type]
                        if av < m:
                            m = av
                    if m < V[pt]:
                        score -= 3
    need = 5 + (6 * (-mat) if mat < 0 else 0)
    return score >= need

import chess

MOTIF_NAME = 'space, development and initiative dominance near material parity'
MOTIF_DESCRIPTION = 'With material within a fraction of a pawn, the side to move holds a broad concrete edge combining space, central control, development lead, pressure on enemy pieces, king safety, passed pawns and rook placement.'

PV = {chess.PAWN: 100, chess.KNIGHT: 305, chess.BISHOP: 320, chess.ROOK: 500, chess.QUEEN: 900}

def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except Exception:
        return False
    stm = board.turn
    opp = not stm

    def mat(c):
        s = 0
        for pt, v in PV.items():
            s += v * len(board.pieces(pt, c))
        if len(board.pieces(chess.BISHOP, c)) >= 2:
            s += 35
        return s

    diff = mat(stm) - mat(opp)
    if diff < -50 or diff > 85:
        return False

    pawnatt = {}
    for c in (stm, opp):
        s = chess.SquareSet()
        for p in board.pieces(chess.PAWN, c):
            s |= board.attacks(p)
        pawnatt[c] = s

    def rel(sq, c):
        r = chess.square_rank(sq)
        return r if c == chess.WHITE else 7 - r

    def space(c):
        s = 0
        for p in board.pieces(chess.PAWN, c):
            rr = rel(p, c)
            if rr >= 4:
                s += 2 + (rr - 4)
                if 2 <= chess.square_file(p) <= 5:
                    s += 2
        return s

    def undev(c):
        back = 0 if c == chess.WHITE else 7
        n = 0
        for pt in (chess.KNIGHT, chess.BISHOP):
            for p in board.pieces(pt, c):
                if chess.square_rank(p) == back:
                    n += 1
        return n

    def mob(c):
        m = 0
        oth = not c
        for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
            for p in board.pieces(pt, c):
                for t in board.attacks(p):
                    pc = board.piece_at(t)
                    if pc is not None and pc.color == c:
                        continue
                    if t in pawnatt[oth]:
                        continue
                    m += 1
        return m

    def press(c):
        oth = not c
        s = 0
        for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
            v = PV[pt]
            for p in board.pieces(pt, oth):
                a = board.attackers(c, p)
                if not a:
                    continue
                d = board.attackers(oth, p)
                mn = 10000
                for x in a:
                    mn = min(mn, PV.get(board.piece_at(x).piece_type, 10000))
                if len(d) == 0:
                    s += 40 + v // 8
                elif mn < v - 60:
                    s += 30 + (v - mn) // 8
                elif len(a) > len(d):
                    s += 18
                else:
                    s += 6
        return s

    def ksaf(c):
        k = board.king(c)
        if k is None:
            return 0
        oth = not c
        s = 0
        kf = chess.square_file(k)
        kr = chess.square_rank(k)
        fwd = 1 if c == chess.WHITE else -1
        for df in (-1, 0, 1):
            f = kf + df
            if 0 <= f <= 7:
                for dr in (1, 2):
                    r = kr + fwd * dr
                    if 0 <= r <= 7:
                        pc = board.piece_at(chess.square(f, r))
                        if pc is not None and pc.piece_type == chess.PAWN and pc.color == c:
                            s += 3 if dr == 1 else 1
                            break
        att = 0
        for sq in board.attacks(k):
            att += len(board.attackers(oth, sq))
        s -= 2 * att
        return s

    def passers(c):
        oth = not c
        tot = 0
        for p in board.pieces(chess.PAWN, c):
            f = chess.square_file(p)
            r = chess.square_rank(p)
            rng = range(r + 1, 8) if c == chess.WHITE else range(0, r)
            passed = True
            for ff in (f - 1, f, f + 1):
                if passed and 0 <= ff <= 7:
                    for rr in rng:
                        pc = board.piece_at(chess.square(ff, rr))
                        if pc is not None and pc.piece_type == chess.PAWN and pc.color == oth:
                            passed = False
                            break
            if passed:
                rr2 = rel(p, c)
                tot += 3 + 2 * (rr2 - 1) + (4 if rr2 >= 5 else 0)
        return tot

    def rooks(c):
        s = 0
        for rsq in board.pieces(chess.ROOK, c):
            f = chess.square_file(rsq)
            own = 0
            foe = 0
            for rr in range(8):
                pc = board.piece_at(chess.square(f, rr))
                if pc is not None and pc.piece_type == chess.PAWN:
                    if pc.color == c:
                        own += 1
                    else:
                        foe += 1
            if own == 0:
                s += 2 if foe == 0 else 1
            if rel(rsq, c) == 6:
                s += 2
        return s

    score = diff
    score += 6 * (space(stm) - space(opp))
    cc = 0
    for sq in (chess.D4, chess.E4, chess.D5, chess.E5):
        cc += len(board.attackers(stm, sq)) - len(board.attackers(opp, sq))
        pcc = board.piece_at(sq)
        if pcc is not None and pcc.piece_type == chess.PAWN:
            cc += 1 if pcc.color == stm else -1
    score += 5 * cc
    score += 12 * (undev(opp) - undev(stm))
    score += 3 * (mob(stm) - mob(opp))
    score += press(stm) - (9 * press(opp)) // 10
    score += 4 * (ksaf(stm) - ksaf(opp))
    score += 3 * (passers(stm) - passers(opp))
    score += 6 * (rooks(stm) - rooks(opp))
    if board.is_check():
        score -= 30
    return score >= 75

MOTIF_NAME = 'pawn health and piece activity superiority at equal material'
MOTIF_DESCRIPTION = 'Material is exactly equal but the side to move has clearly healthier pawns, better passed pawns, more active rooks and outposts, a safer king and more pressure on the enemy king zone.'

import chess

def motif(fen: str) -> bool:
    try:
        b = chess.Board(fen)
    except Exception:
        return False
    stm = b.turn
    V = {chess.PAWN: 100, chess.KNIGHT: 300, chess.BISHOP: 300, chess.ROOK: 500, chess.QUEEN: 900}
    def mat(c):
        return sum(v * len(b.pieces(p, c)) for p, v in V.items())
    if mat(stm) != mat(not stm):
        return False
    def rel(r, c):
        return r if c else 7 - r
    def score(c):
        e = not c
        s = 0
        pawns = b.pieces(chess.PAWN, c)
        epawns = b.pieces(chess.PAWN, e)
        pf = [chess.square_file(p) for p in pawns]
        for p in pawns:
            f = chess.square_file(p)
            r = chess.square_rank(p)
            rr = rel(r, c)
            if not any(abs(x - f) == 1 for x in pf):
                s -= 10
            passed = True
            for q in epawns:
                if abs(chess.square_file(q) - f) <= 1:
                    qr = chess.square_rank(q)
                    if (c and qr > r) or ((not c) and qr < r):
                        passed = False
                        break
            if passed:
                s += 18
                if rr > 3:
                    s += 14 * (rr - 3)
            if 2 <= f <= 5 and rr >= 4:
                s += 5
        for f in set(pf):
            s -= 12 * (pf.count(f) - 1)
        for sq in b.pieces(chess.ROOK, c):
            f = chess.square_file(sq)
            rr = rel(chess.square_rank(sq), c)
            if f not in pf:
                s += 10
                if all(chess.square_file(q) != f for q in epawns):
                    s += 10
            if rr >= 5:
                s += 10
                if rr >= 6:
                    s += 15
        for sq in b.pieces(chess.KNIGHT, c):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            rr = rel(r, c)
            if 3 <= rr <= 5:
