    op_pf = set(chess.square_file(p) for p in op_p)

    my_h = list(board.pieces(chess.ROOK, stm)) + list(board.pieces(chess.QUEEN, stm))
    op_h = list(board.pieces(chess.ROOK, opp)) + list(board.pieces(chess.QUEEN, opp))
    for f in range(8):
        if f in my_pf or f in op_pf:
            continue
        if sum(1 for h in my_h if chess.square_file(h) == f) >= 2 and \
           all(chess.square_file(h) != f for h in op_h):
            return True

    adv = [p for p in my_p if rrank(p, stm) >= 5]
    for p in adv:
        for q in adv:
            if q <= p or abs(chess.square_file(p) - chess.square_file(q)) != 1:
                continue
            if any(board.piece_type_at(a) == chess.PAWN for a in board.attackers(opp, p)):
                continue
            if any(board.piece_type_at(a) == chess.PAWN for a in board.attackers(opp, q)):
                continue
            if any(board.piece_type_at(a) == chess.PAWN for a in board.attackers(stm, p)) or \
               any(board.piece_type_at(a) == chess.PAWN for a in board.attackers(stm, q)):
                return True

    def blocked_cnt(color, comp):
        n = 0
        step = 8 if color == chess.WHITE else -8
        for p in board.pieces(chess.PAWN, color):
            if (chess.square_file(p) + chess.square_rank(p)) % 2 != comp:
                continue
            fr = p + step
            if 0 <= fr < 64 and board.piece_at(fr) is not None:
                n += 1
        return n

    bad_theirs = any(blocked_cnt(opp, (chess.square_file(b) + chess.square_rank(b)) % 2) >= 3
                     for b in board.pieces(chess.BISHOP, opp))
    bad_ours = any(blocked_cnt(stm, (chess.square_file(b) + chess.square_rank(b)) % 2) >= 2
                   for b in board.pieces(chess.BISHOP, stm))
    if bad_theirs and not bad_ours:
        return True

    my_rim = any(chess.square_file(n) in (0, 7) for n in board.pieces(chess.KNIGHT, stm))
    if not my_rim:
        for n in board.pieces(chess.KNIGHT, opp):
            if chess.square_file(n) in (0, 7):
                if not any(board.piece_type_at(a) == chess.PAWN for a in board.attackers(opp, n)):
                    return True

    op_rooks = list(board.pieces(chess.ROOK, opp))
    if len(op_rooks) >= 2:
