        for r in op_rooks:
            if rrank(r, opp) > 2:
                shut = False
                break
            f = chess.square_file(r)
            if not any(chess.square_file(p) == f and rrank(p, opp) > rrank(r, opp) for p in op_p):
                shut = False
                break
        if shut and any(chess.square_file(h) not in my_pf for h in board.pieces(chess.ROOK, stm)):
            return True

    def defects(pawns):
        cf = {}
        for p in pawns:
            f = chess.square_file(p)
            cf[f] = cf.get(f, 0) + 1
        d = 0
        for f, c in cf.items():
            d += c - 1
            if cf.get(f - 1, 0) == 0 and cf.get(f + 1, 0) == 0:
                d += c
        return d

    if defects(op_p) - defects(my_p) >= 3:
        return True
    return False

