    def rel(sq, c):
        r = chess.square_rank(sq)
        return r if c == chess.WHITE else 7 - r
    for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        for sq in board.pieces(pt, stm):
            atk = board.attackers(opp, sq)
            if not atk:
                continue
            if not board.attackers(stm, sq):
