    qs = len(board.pieces(chess.QUEEN, stm))
    qo = len(board.pieces(chess.QUEEN, opp))
    def shel(c, k):
        kf = chess.square_file(k)
        kr = rel(k, c)
        n = 0
        for p in board.pieces(chess.PAWN, c):
            if abs(chess.square_file(p) - kf) <= 1:
