    su = shel(stm, ok)
    so = shel(opp, ek)
    if qs >= 1 and qo >= 1 and rel(ok, stm) <= 1 and rel(ek, opp) <= 1:
        if su >= 2 and su - so >= 2:
            return True
    if qs >= 1 and rel(ek, opp) <= 1 and su >= so + 1:
        ekf = chess.square_file(ek)
        for f in (ekf - 1, ekf, ekf + 1):
            if f < 0 or f > 7:
                continue
            open_f = True
            for p in board.pieces(chess.PAWN, opp):
                if chess.square_file(p) == f:
