    if qs == 0 and qo == 0:
        def passers(c):
            e = not c
            res = []
            for p in board.pieces(chess.PAWN, c):
                pf = chess.square_file(p)
                pr = rel(p, c)
                blk = False
                for q in board.pieces(chess.PAWN, e):
                    if abs(chess.square_file(q) - pf) <= 1 and rel(q, c) > pr:
                        blk = True
                        break
                if not blk:
                    res.append(pr)
            return res
        pu = passers(stm)
        po = passers(opp)
        S = 2 * max(-2, min(2, len(pu) - len(po)))
        if pu and max(pu) >= 4:
            S += 1
        if po and max(po) >= 4:
            S -= 1
        C = (chess.D4, chess.E4, chess.D5, chess.E5)
        dko = min(chess.square_distance(ok, cc) for cc in C)
        dke = min(chess.square_distance(ek, cc) for cc in C)
        S += max(-2, min(2, dke - dko))
        def ract(c):
            n = 0
            for r in board.pieces(chess.ROOK, c):
                f = chess.square_file(r)
                own = False
                for p in board.pieces(chess.PAWN, c):
                    if chess.square_file(p) == f:
                        own = True
                        break
                if not own:
                    n += 1
                if rel(r, c) >= 6:
                    n += 1
            return n
        S += max(-2, min(2, ract(stm) - ract(opp)))
        def iso(c):
            fs = set(chess.square_file(p) for p in board.pieces(chess.PAWN, c))
            n = 0
            for p in board.pieces(chess.PAWN, c):
                f = chess.square_file(p)
                if (f - 1) not in fs and (f + 1) not in fs:
                    n += 1
            return n
        S += max(-2, min(2, iso(opp) - iso(stm)))
        S += max(-2, min(2, rel(ok, stm) - rel(ek, opp)))
        if S >= 5:
            return True
    return False

