_V = (0, 1, 3, 3, 5, 9, 12)

def _see(board, mv):
    to = mv.to_square
    ep = board.is_en_passant(mv)
    if ep:
        cap = 1
    else:
        tp = board.piece_at(to)
        if tp is None or tp.piece_type == 6:
            return 0
        cap = _V[tp.piece_type]
    b = board.copy(stack=False)
    mover = b.piece_at(mv.from_square)
    if mover is None:
        return 0
    b.remove_piece_at(mv.from_square)
    if ep:
        b.remove_piece_at(chess.square(chess.square_file(to), chess.square_rank(mv.from_square)))
    b.remove_piece_at(to)
    b.set_piece_at(to, mover)
    gains = [cap]
    occv = _V[mover.piece_type]
    color = not mover.color
    for _ in range(34):
        a = None
        av = 99
        for s in b.attackers(color, to):
            v = _V[b.piece_at(s).piece_type]
            if v < av:
                av = v
                a = s
        if a is None:
            break
        p = b.piece_at(a)
        if p.piece_type == 6:
            b.remove_piece_at(a)
            b.remove_piece_at(to)
            b.set_piece_at(to, p)
            if not b.attackers(not color, to):
                gains.append(occv - gains[-1])
            break
        gains.append(occv - gains[-1])
        occv = _V[p.piece_type]
        b.remove_piece_at(a)
        b.remove_piece_at(to)
        b.set_piece_at(to, p)
        color = not color
    while len(gains) > 1:
        g = gains.pop()
        gains[-1] = -max(-gains[-1], g)
    return gains[0]

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    mat = 0
    for p in board.piece_map().values():
        if p.piece_type != 6:
            mat += _V[p.piece_type] if p.color == stm else -_V[p.piece_type]
    if mat > -1:
        return False
    best = None
    bestv = -99
    tgt = {}
    for mv in board.legal_moves:
        if not board.is_capture(mv):
            continue
        v = _see(board, mv)
        t = mv.to_square
        if v > tgt.get(t, -99):
            tgt[t] = v
        if v > bestv:
            bestv = v
            best = mv
    if best is None or bestv < 1 or mat + bestv < 0:
        return False
    board.push(best)
    worst = 0
    ts = best.to_square
    for mv in board.legal_moves:
        if board.is_capture(mv) and mv.to_square != ts:
            v = _see(board, mv)
            if v > worst:
                worst = v
    board.pop()
    if mat + bestv - worst >= 1:
        return True
    if mat == -1 and worst == 0:
        cnt = 0
        for t in tgt:
            if tgt[t] >= 1:
                cnt += 1
        if cnt >= 2:
            return True
    return False

