_V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 20}

def _see(board, mv):
    t = mv.to_square
    b = board.copy(stack=False)
    gains = []
    cur = mv
    n = 0
    while n < 10:
        n += 1
        if b.is_en_passant(cur):
            v = 1
        else:
            p = b.piece_at(t)
            v = _V[p.piece_type] if p else 0
        gains.append(v)
        b.push(cur)
        best = None
        bv = 99
        for m in b.legal_moves:
            if m.to_square == t and b.is_capture(m):
                w = _V[b.piece_at(m.from_square).piece_type]
                if w < bv:
                    bv = w
                    best = m
        if best is None:
            break
        cur = best
    res = 0
    i = len(gains) - 1
    while i > 0:
        g = gains[i] - res
        res = g if g > 0 else 0
        i -= 1
    return gains[0] - res

def _feats(b, c):
    P = list(b.pieces(chess.PAWN, c))
    EP = list(b.pieces(chess.PAWN, not c))
    files = [chess.square_file(s) for s in P]
    weak = 0
    for s in P:
        f = chess.square_file(s)
        if (f - 1) not in files and (f + 1) not in files:
            weak += 1
    for f in set(files):
        weak += files.count(f) - 1
    pas = 0
    for s in P:
        f = chess.square_file(s)
        r = chess.square_rank(s)
        rr = r if c else 7 - r
        stop = False
        for e in EP:
            if abs(chess.square_file(e) - f) <= 1:
                er = chess.square_rank(e)
                if (c and er > r) or ((not c) and er < r):
                    stop = True
                    break
        if not stop and rr >= 4:
            pas += 1
    ks = b.king(c)
    ko = b.king(not c)
    atk = set()
    if ko is not None:
        for s in b.attacks(ko):
            for a in b.attackers(c, s):
                if a != ks:
                    atk.add(a)
    rk = 0
    for s in b.pieces(chess.ROOK, c):
        if chess.square_file(s) not in files:
            rk += 1
    pair = 1 if len(b.pieces(chess.BISHOP, c)) >= 2 else 0
    sh = 0
    if ks is not None:
        for s in P:
            if chess.square_distance(s, ks) <= 2:
                sh += 1
    return weak, min(pas, 2), min(len(atk), 4), min(rk, 2), pair, min(sh, 3)

def _clip(x, lo, hi):
    return lo if x < lo else (hi if x > hi else x)

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    d = 0
    for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        d += _V[pt] * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
    if d > -1:
        return False
    best = None
    bg = -99
    bw = 99
    for m in board.legal_moves:
        if not board.is_capture(m):
            continue
        g = _see(board, m)
        w = _V[board.piece_at(m.from_square).piece_type]
        if g > bg or (g == bg and w < bw):
            bg = g
            bw = w
            best = m
    if best is None:
        return False
    net = bg + d
    if net < 0 or net > 2:
        return False
    b2 = board.copy(stack=False)
    b2.push(best)
    for m in b2.legal_moves:
        if b2.is_capture(m) and _see(b2, m) >= 1:
            return False
    w1, p1, a1, r1, bp1, s1 = _feats(b2, stm)
    w2, p2, a2, r2, bp2, s2 = _feats(b2, opp)
    S = _clip(w2 - w1, -2, 2) + _clip(p1 - p2, -2, 2) + _clip(a1 - a2, -2, 2) + (r1 - r2) + (bp1 - bp2) + _clip(s1 - s2, -1, 1)
    need = 1 if d <= -2 else 2
    if net >= 1:
        need -= 2
    return S >= need

