                    esc += 1
                    continue
                mn = min(v[board.piece_at(a).piece_type] for a in a2)
                d2 = [d for d in board.attackers(opp, s) if d != sq]
                if mn >= v[pt] and d2:
                    esc += 1
            if esc == 0:
                return True
    return False

