def _rr(c, sq):
    r = chess.square_rank(sq)
    return r if c == chess.WHITE else 7 - r

def _shield(b, c, k):
    kf = chess.square_file(k)
    kr = chess.square_rank(k)
    d = 1 if c == chess.WHITE else -1
    n = 0
    for df in (-1, 0, 1):
        f = kf + df
        if f < 0 or f > 7:
            continue
        for dr in (1, 2):
            r = kr + d * dr
            if 0 <= r <= 7:
                p = b.piece_at(chess.square(f, r))
                if p and p.piece_type == chess.PAWN and p.color == c:
                    n += 1
                    break
    return n

def _minatt(b, c, sq):
    m = 99
    for a in b.attackers(c, sq):
        p = b.piece_at(a)
        v = 10 if p.piece_type == chess.KING else _V[p.piece_type]
        if v < m:
            m = v
    return m

def _loose(b, s):
    o = not s
    for pt in (2, 3, 4, 5):
        for sq in b.pieces(pt, s):
            if not b.attackers(o, sq):
                continue
            if _minatt(b, o, sq) < _V[pt]:
                return True
            if not b.attackers(s, sq):
                return True
    return False

def _np(b, c):
    t = 0
    for pt in (2, 3, 4, 5):
        t += _V[pt] * len(b.pieces(pt, c))
    return t

def motif(fen: str) -> bool:
    try:
        b = chess.Board(fen)
    except Exception:
        return False
    s = b.turn
    o = not s
    md = _md(b, s)
    if b.is_check():
        cks = list(b.checkers())
        if len(cks) != 1:
            return False
        c = cks[0]
        cp = b.piece_at(c)
        cv = _V[cp.piece_type]
        if md + cv < 2:
            return False
        defs = len(b.attackers(o, c))
        for a in b.attackers(s, c):
            pa = b.piece_at(a)
            if pa.piece_type == chess.KING:
                if defs == 0:
                    return True
                continue
            if b.is_pinned(s, a):
                continue
            if defs == 0 or _V[pa.piece_type] < cv:
                return True
        return False
    mk = b.king(s)
    ok = b.king(o)
    if mk is None or ok is None:
        return False
    myq = len(b.pieces(chess.QUEEN, s)) > 0
    opq = len(b.pieces(chess.QUEEN, o)) > 0
    okr = _rr(o, ok)
    okf = chess.square_file(ok)
    mkr = _rr(s, mk)
    mkf = chess.square_file(mk)
    if md >= -2 and myq and not _loose(b, s):
        if okr >= 2 and mkr <= 1 and _np(b, o) >= 10:
            return True
        if okr == 0 and 2 <= okf <= 5 and not b.has_castling_rights(o) and (opq or _np(b, s) >= 16):
            if mkf in (0, 1, 2, 6, 7) and mkr <= 1:
                ss = _shield(b, s, mk)
                osd = _shield(b, o, ok)
                if ss >= 1 and ss >= osd and osd <= 2:
                    lft = False
                    rgt = False
                    bk = 0 if o == chess.WHITE else 7
                    for rsq in b.pieces(chess.ROOK, o):
                        if chess.square_rank(rsq) == bk:
                            if chess.square_file(rsq) < okf:
                                lft = True
                            elif chess.square_file(rsq) > okf:
                                rgt = True
                    if (lft and rgt) or okf in (3, 4):
                        return True
    for q in b.pieces(chess.QUEEN, o):
        am = 99
        for a in b.attackers(s, q):
            p = b.piece_at(a)
            if p.piece_type == chess.KING or p.piece_type == chess.QUEEN:
                continue
            if b.is_pinned(s, a):
                continue
            if _V[p.piece_type] < am:
                am = _V[p.piece_type]
        if am > 8:
            continue
        if md + 9 - am < 1 or _loose(b, s):
            continue
        esc = False
        for e in b.attacks(q):
            p = b.piece_at(e)
            if p and p.color == o:
                continue
            if not b.attackers(s, e):
                esc = True
                break
        if not esc:
            return True
    return False

import chess

MOTIF_NAME = 'queen-led siege of a castling-less central enemy king'
MOTIF_DESCRIPTION = 'At material parity or down at most one pawn, the side to move keeps its queen and a secure king while the enemy king is stuck on the d, e or f file near its home rank with no castling rights, backed by an adjacent half-open file, king-ring pressure or a development lead.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    if board.is_check():
        return False
    vals = (0, 1, 3, 3, 5, 9)
    md = 0
    for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        md += vals[pt] * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
    if md < -1 or md > 0:
        return False
    if not board.pieces(chess.QUEEN, stm):
        return False
    if board.has_castling_rights(opp):
        return False
    ek = board.king(opp)
    kk = board.king(stm)
    if ek is None or kk is None:
        return False
    home_o = 0 if opp == chess.WHITE else 7
    home_s = 0 if stm == chess.WHITE else 7
    ef = chess.square_file(ek)
    er = chess.square_rank(ek)
    if ef < 3 or ef > 5:
        return False
    rank_ok = (er == home_o) or (home_o == 0 and er == 1) or (home_o == 7 and er == 6)
    if not rank_ok:
        return False
    own_ok = board.has_castling_rights(stm) or (chess.square_rank(kk) == home_s and chess.square_file(kk) in (1, 2, 6, 7))
    if not own_ok:
        return False
    opf = [0, 0, 0, 0, 0, 0, 0, 0]
    for s in board.pieces(chess.PAWN, opp):
        opf[chess.square_file(s)] += 1
    half_open = False
    for f in (ef - 1, ef, ef + 1):
        if 0 <= f <= 7 and opf[f] == 0:
            half_open = True
    pressure = 0
    for s in board.attacks(ek):
        pressure += len(board.attackers(stm, s))
    dev = 0
    for pt in (chess.KNIGHT, chess.BISHOP):
        for s in board.pieces(pt, stm):
            if chess.square_rank(s) != home_s:
                dev += 1
        for s in board.pieces(pt, opp):
            if chess.square_rank(s) != home_o:
                dev -= 1
    score = 0
    if half_open:
        score += 1
    if pressure >= 1:
        score += 1
    if pressure >= 3:
        score += 1
    if dev >= 2:
        score += 1
    need = 2 if md == 0 else 3
    return score >= need

import chess

MOTIF_NAME = 'wrecked enemy king shelter with attacker surplus near parity'
MOTIF_DESCRIPTION = 'Near material parity with its queen still on board and its own king ring not swarmed, the side to move besieges an enemy king whose pawn shelter is destroyed or clearly inferior, holding strictly more distinct attackers on the enemy king ring than the opponent has on its own.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    if board.is_check():
        return False
    if not board.pieces(chess.QUEEN, stm):
        return False
    V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3,
         chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 0}
    d = 0
    for sq, pc in board.piece_map().items():
        v = V[pc.piece_type]
        d += v if pc.color == stm else -v
    if d < -1 or d > 2:
        return False
    mk = board.king(stm)
    ek = board.king(opp)
    if mk is None or ek is None:
        return False

    def shield(k, c):
        rr = chess.square_rank(k) if c == chess.WHITE else 7 - chess.square_rank(k)
        if rr >= 3:
            return 0
        kf = chess.square_file(k)
        kr = chess.square_rank(k)
        step = 1 if c == chess.WHITE else -1
        n = 0
        for df in (-1, 0, 1):
            f = kf + df
            if f < 0 or f > 7:
                continue
            for dr in (1, 2):
                r = kr + step * dr
                if 0 <= r <= 7:
                    p = board.piece_at(chess.square(f, r))
                    if p is not None and p.piece_type == chess.PAWN and p.color == c:
                        n += 1
                        break
        return n

    esh = shield(ek, opp)
    msh = shield(mk, stm)

    def ring(k, c, excl):
        s = set()
        for t in board.attacks(k):
            for a in board.attackers(c, t):
                if a != excl:
                    s.add(a)
        return len(s)

    myr = ring(ek, stm, mk)
    opr = ring(mk, opp, ek)
    if myr < 2 or opr > 2:
        return False
    if esh == 0 and myr - opr >= 1:
        return True
    if esh <= 1 and myr - opr >= 2:
        return True
    if msh - esh >= 2 and myr - opr >= 2:
        return True
    if myr >= 4 and opr <= 1:
        return True
    return False
